/// <summary>
///     AVA - Schneider 24.07.2024
///     AVA <c>avaHasShippingAbility</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display boolean avaHasShippingAbility()
{
    boolean retVal;

    retVal = this.AVAShippingAbility != AVAShippingAbility::No;

    return retVal;
}
